package lab.commerceflow.storefront.mapper;import lab.commerceflow.storefront.domain.*;import java.math.BigDecimal;import java.util.*;import org.apache.ibatis.annotations.*;public interface ReviewMapper{@Select("SELECT i.id order_item_id,i.product_id FROM order_items i JOIN shop_orders o ON o.id=i.order_id WHERE i.id=#{itemId} AND o.customer_id=#{customerId} AND o.status IN ('RECEIVED','COMPLETED')")Optional<ReviewableItem> reviewable(@Param("customerId")Long customerId,@Param("itemId")Long itemId);@Insert("INSERT INTO product_reviews(order_item_id,product_id,customer_id,rating,comment) VALUES(#{itemId},#{productId},#{customerId},#{rating},#{comment})")void insert(@Param("itemId")Long itemId,@Param("productId")Long productId,@Param("customerId")Long customerId,@Param("rating")int rating,@Param("comment")String comment);@Select("SELECT r.*,CONCAT(u.first_name,' ',u.last_name) reviewer_name FROM product_reviews r JOIN app_users u ON u.id=r.customer_id WHERE r.order_item_id=#{itemId}")ProductReviewView byItem(Long itemId);@Select("SELECT r.*,CONCAT(u.first_name,' ',u.last_name) reviewer_name FROM product_reviews r JOIN app_users u ON u.id=r.customer_id WHERE r.product_id=#{productId} ORDER BY r.created_at DESC")List<ProductReviewView> reviews(Long productId);@Select("SELECT COALESCE(AVG(rating),0) FROM product_reviews WHERE product_id=#{productId}")BigDecimal average(Long productId);@Select("SELECT COUNT(*) FROM product_reviews WHERE product_id=#{productId}")int count(Long productId);}
